"""Phase 7: the two dossiers (11 expert-needed rules; per-variant academic profile). They are generated by tools/build_phase7_dossier.py from pinned data; the tests check that
nothing is promoted to 'verified', that every number in them equals the pinned scan, and that every cited passage is real."""
import json
import sys
from pathlib import Path

import pytest

ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(Path(__file__).resolve().parent))
RULES = json.loads((ROOT / "engine/data/experimental/formation_rule_dossier.json").read_text("utf-8"))["rules"]
VARS = json.loads((ROOT / "engine/data/experimental/formation_variant_dossier.json").read_text("utf-8"))["variants"]
RD = json.loads((ROOT / "engine/tests/fixtures/readings_sensitivity.json").read_text("utf-8"))
TH = json.loads((ROOT / "engine/tests/fixtures/tu_hoa_sensitivity.json").read_text("utf-8"))
META = json.loads((ROOT / "engine/data/experimental/formations_school_variants.json").read_text("utf-8"))["meta"]
ST = json.loads((ROOT / "engine/tests/fixtures/formation_variant_stats.json").read_text("utf-8"))


def test_eleven_rules_are_open_with_a_classification_and_no_verified_stamp():
    assert [r["id"] for r in RULES] == [f"R{i:02d}" for i in range(1, 12)]
    assert {r["classification"] for r in RULES} <= {"nguon_xac_nhan", "nguon_mau_thuan", "nguon_chua_du"}
    by = {r["id"]: r["classification"] for r in RULES}
    assert by["R05"] == "nguon_mau_thuan" and by["R07"] == "nguon_mau_thuan" and by["R10"] == "nguon_xac_nhan" and by["R01"] == "nguon_chua_du"
    blob = json.dumps(RULES, ensure_ascii=False).lower()
    assert '"verified": true' not in blob and "verified" not in blob.replace("không bao giờ được xếp", "")
    for r in RULES:
        assert r["question"] and r["current"] and (r["decision"] or r["id"] == "R10")
        assert r["trang_thai"].startswith("mo") or r["id"] == "R10"


def test_every_passage_has_page_quote_how_and_context_or_an_image_note():
    for r in RULES:
        for p in r["passages"]:
            assert p["page"] and p["quote"] and p["how"] in ("van_ban", "anh_doc_ro"), (r["id"], p["id"])
            assert isinstance(p["context"], dict) and (p["context"]["truoc"] or p["context"]["sau"]) or "đọc trực tiếp từ ảnh" in p["context"], (r["id"], p["id"])
    nham = next(r for r in RULES if r["id"] == "R05")
    assert len(nham["extra"]) == 5 and any("zh.wikisource" in e["book"] for e in nham["extra"]) and any(e["book"] == "TH" and e["page"] == 20 for e in nham["extra"])
    assert "không phải lỗi in" in nham["verdict"].lower() and "chưa có bằng chứng chọn bên nào" in nham["verdict"]


def test_numbers_in_the_dossier_equal_the_pinned_scans():
    r2 = next(r for r in RULES if r["id"] == "R02")["impact"]["bang"]
    assert r2["tp|mot_trong_ba"] == round(100 * RD["A"]["tp|mot_trong_ba"] / RD["A_core"]["n"], 1) == 82.1
    r5 = next(r for r in RULES if r["id"] == "R05")["impact"]
    assert r5["Canh"] == TH["Canh|TT_WS"]["differ"] == {} and r5["Nham"] == TH["Nhâm|TH"]["differ"]
    r6 = next(r for r in RULES if r["id"] == "R06")["impact"]
    assert (r6["so_la_so"], r6["tren"]) == (3456, 25728)
    r9 = next(r for r in RULES if r["id"] == "R09")["impact"]
    assert r9["tu_phu_dong_cung_o_menh"] == 1920 and r9["tu_phu_dong_cung_o_than_khong_o_menh"] == 1440 and r9["tu_phu_dong_cung_o_ty_hoi_bat_ky"] == 0


def test_variant_dossier_covers_all_variants_and_agrees_with_the_meta():
    assert [v["id"] for v in VARS] == list(META)
    for v in VARS:
        m = META[v["id"]]
        assert {r["key"]: r["level"] for r in v["rules"]} == m["rules"] and v["verified"] is False
        assert v["school"] == m["school_vi"] and v["rescuers"].startswith("không có")
        for r in v["rules"]:
            assert r["cites"] and all(c["quote"] and c["page"] for c in r["cites"])
            if r["level"] == "doi_chieu_truc_tiep":
                assert not r["assumption"] and all(c["how"] == "van_ban" for c in r["cites"])
        assert v["kich_hoat_pct"] == round(100 * sum(q for s, q in ST["states"][v["id"]].items() if s != "khong_hien") / ST["charts"], 2)


def test_conflicting_variants_are_listed_both_ways_and_never_merged():
    by = {v["id"]: v for v in VARS}
    a, b = by["CACH_X_CO_NGUYET_DONG_LUONG@tt_24"], by["CACH_X_CO_NGUYET_DONG_LUONG@kl_221"]
    assert [c["variant"] for c in a["conflicting_variants"]] == [b["id"]] and [c["variant"] for c in b["conflicting_variants"]] == [a["id"]]
    assert a["conflicting_variants"][0]["khac_nhau"] == b["conflicting_variants"][0]["khac_nhau"] == 14352
    thach = [v for v in VARS if v["base"] == "CACH_X_THACH_TRUNG_AN_NGOC"]
    assert len(thach) == 3 and all(len(v["conflicting_variants"]) == 2 for v in thach)
    assert all(v["conflicting_variants"] == [] for v in VARS if v["base"] in ("CACH_X_NHAT_LE_TRUNG_THIEN", "CACH_X_TAM_KY_GIA_HOI", "CACH_X_KHOI_VIET_GIAP_MENH"))


def test_contexts_come_from_the_pdf_when_present():
    pytest.importorskip("fitz")
    sys.path.insert(0, str(ROOT / "tools"))
    import book_text as bt
    if not bt.available("TT"):
        pytest.skip("books not available")
    tt24 = next(p for r in RULES if r["id"] == "R02" for p in r["passages"] if p["id"] == "TT24_CNDL_BREAK")
    assert "công chức quèn" in tt24["context"]["truoc"] and bt.quote_on_page("TT", 24, tt24["quote"])
